/*
 * nano_j2me - test_font_png.c
 *
 * Assertion-based tests for the bitmap fonts (src/gfx/nj_font.c, generated by
 * tools/gen_fonts.py) and the PNG decoder (src/gfx/nj_png.c).
 *
 * Fixtures come from tests/gen_png_fixtures.py; every positive fixture is
 * compared pixel for pixel against a raw ARGB8888 dump that Pillow (libpng)
 * independently agreed with when the fixtures were generated.
 *
 * Build:
 *   gcc -std=c99 -Wall -Wextra -Werror -pedantic -Iinclude -DNJ_USE_LIBC=1 \
 *       -o /tmp/test_font_png tests/test_font_png.c src/gfx/nj_png.c \
 *       src/gfx/nj_font.c src/zip/nj_inflate.c -lm
 * Run:
 *   /tmp/test_font_png [fixture-dir]      (default tests/fixtures/png)
 */

#include "nj2me/nj_gfx.h"
#include "nj2me/nj_png.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* ------------------------------------------------------------------ */
/* Tiny check framework                                                */
/* ------------------------------------------------------------------ */
static int g_checks;
static int g_failures;

#define CHECK(cond, ...)                                                  \
    do {                                                                  \
        g_checks++;                                                       \
        if (!(cond)) {                                                    \
            g_failures++;                                                 \
            printf("FAIL %s:%d: ", __FILE__, __LINE__);                   \
            printf(__VA_ARGS__);                                          \
            printf("\n");                                                 \
        }                                                                 \
    } while (0)

#define CHECK_EQ_INT(got, want, what)                                     \
    do {                                                                  \
        long long g_ = (long long)(got);                                  \
        long long w_ = (long long)(want);                                 \
        CHECK(g_ == w_, "%s: got %lld, want %lld", (what), g_, w_);       \
    } while (0)

static void *xread(const char *path, size_t *size_out)
{
    FILE *fh = fopen(path, "rb");
    long len;
    void *buf;

    if (fh == NULL) {
        return NULL;
    }
    if (fseek(fh, 0, SEEK_END) != 0) {
        fclose(fh);
        return NULL;
    }
    len = ftell(fh);
    if (len < 0 || fseek(fh, 0, SEEK_SET) != 0) {
        fclose(fh);
        return NULL;
    }
    buf = malloc((size_t)len + 1u);
    if (buf == NULL) {
        fclose(fh);
        return NULL;
    }
    if (len > 0 && fread(buf, 1u, (size_t)len, fh) != (size_t)len) {
        free(buf);
        fclose(fh);
        return NULL;
    }
    fclose(fh);
    *size_out = (size_t)len;
    return buf;
}

/* ------------------------------------------------------------------ */
/* Counting allocator: proves every intermediate buffer is released     */
/* ------------------------------------------------------------------ */
typedef struct alloc_stats {
    int      allocs;
    int      frees;
    size_t   bytes;
} alloc_stats;

static void *counting_alloc(void *ud, nj_size size)
{
    alloc_stats *st = (alloc_stats *)ud;

    st->allocs++;
    st->bytes += size;
    return malloc((size_t)size);
}

static void counting_free(void *ud, void *p)
{
    alloc_stats *st = (alloc_stats *)ud;

    st->frees++;
    free(p);
}

/* ------------------------------------------------------------------ */
/* Font tests                                                          */
/* ------------------------------------------------------------------ */
static int count_ink_rows(const nj_font *f, nj_u2 ch)
{
    int row_bytes = f->bitmap_coverage == 2
                        ? (f->glyph_w * 2 + 7) / 8
                        : (f->glyph_w + 7) / 8;
    const nj_u1 *bits;
    int y;
    int x;
    int total = 0;

    if (ch < f->first_char || ch > f->last_char || f->bitmap == NULL) {
        return -1;
    }
    bits = f->bitmap + (size_t)(ch - f->first_char) *
           (size_t)row_bytes * (size_t)f->glyph_h;
    for (y = 0; y < f->glyph_h; y++) {
        for (x = 0; x < f->glyph_w; x++) {
            if (f->bitmap_coverage == 2
                    ? ((bits[y * row_bytes + (x >> 2)] >> (6 - 2 * (x & 3))) & 3u)
                    : ((bits[y * row_bytes + (x >> 3)] >> (7 - (x & 7))) & 1u)) {
                total++;
            }
        }
    }
    return total;
}

/* A fake CJK-ish provider used to exercise the fallback machinery. */
static const nj_u1 *fake_lookup(void *ud, nj_u2 ch, int *w, int *h)
{
    static const nj_u1 bits[2] = { 0xC0u, 0xC0u };

    (void)ud;
    /* U+3400 is CJK Ext-A: outside GB2312, so the built-in table leaves it
     * alone and this fake stays the only thing that can claim it. */
    if (ch != 0x3400u) {
        return NULL;
    }
    *w = 16;
    *h = 16;
    return bits;
}

static int fake_advance(void *ud, nj_u2 ch)
{
    (void)ud;
    return (ch == 0x3400u) ? 15 : 7;
}

static void test_font_builtin_table(void)
{
    static const int sizes[3] = {
        NJ_FONT_SIZE_SMALL, NJ_FONT_SIZE_MEDIUM, NJ_FONT_SIZE_LARGE
    };
    static const int styles[6] = {
        NJ_FONT_STYLE_PLAIN, NJ_FONT_STYLE_BOLD, NJ_FONT_STYLE_ITALIC,
        NJ_FONT_STYLE_BOLD | NJ_FONT_STYLE_ITALIC, NJ_FONT_STYLE_UNDERLINED,
        NJ_FONT_STYLE_BOLD | NJ_FONT_STYLE_ITALIC | NJ_FONT_STYLE_UNDERLINED
    };
    int i;
    int j;

    for (i = 0; i < 3; i++) {
        for (j = 0; j < 6; j++) {
            const nj_font *f = nj_font_builtin(sizes[i], styles[j]);
            const int mask = NJ_FONT_STYLE_BOLD | NJ_FONT_STYLE_ITALIC |
                             NJ_FONT_STYLE_UNDERLINED;

            CHECK(f != NULL, "nj_font_builtin(%d,%d) returned NULL",
                  sizes[i], styles[j]);
            if (f == NULL) {
                continue;
            }
            CHECK(f->bitmap != NULL, "builtin font has no bitmap");
            CHECK(f->glyph_w > 0, "builtin glyph_w is %d", f->glyph_w);
            CHECK(f->glyph_h > 0, "builtin glyph_h is %d", f->glyph_h);
            CHECK(f->ascent + f->descent <= f->height,
                  "ascent %d + descent %d > height %d",
                  f->ascent, f->descent, f->height);
            CHECK(f->ascent > 0 && f->descent >= 0, "bad ascent/descent");
            CHECK(f->first_char == 0x20u && f->last_char == 0xFFu,
                  "unexpected coverage 0x%04X..0x%04X",
                  (unsigned)f->first_char, (unsigned)f->last_char);
            CHECK((f->style & mask) == (styles[j] & mask),
                  "style not recorded: got %d want %d", f->style, styles[j]);
            CHECK(f->size == sizes[i] || (sizes[i] == 0 && f->size == 0),
                  "size not recorded: got %d want %d", f->size, sizes[i]);

            /* Every printable ASCII glyph must have ink; space must not. */
            CHECK(count_ink_rows(f, 0x20) == 0, "space is not blank");
            CHECK(count_ink_rows(f, 'A') > 0, "'A' has no ink");
            CHECK(count_ink_rows(f, 'g') > 0, "'g' has no ink");
            CHECK(count_ink_rows(f, 0xFF) > 0, "U+00FF has no ink");
            /* Sub-byte depths must never touch the next cell over. */
            CHECK(count_ink_rows(f, 0x7Fu) == 0, "U+007F should be blank");
            CHECK(count_ink_rows(f, 0x80u) == 0, "U+0080 should be blank");

            /* An antialiased fixed table must really carry partial edges,
             * not just the old on/off stems at two bits wide. */
            CHECK(f->bitmap_coverage == 0 || f->bitmap_coverage == 2,
                  "builtin fixed table coverage %d", f->bitmap_coverage);
            if (f->bitmap_coverage == 2) {
                const int rb = (f->glyph_w * 2 + 7) / 8;
                const nj_u1 *bits = f->bitmap +
                    (size_t)('A' - f->first_char) *
                        (size_t)rb * (size_t)f->glyph_h;
                int x, y, partial = 0;
                for (y = 0; y < f->glyph_h; y++) {
                    for (x = 0; x < f->glyph_w; x++) {
                        int v = ((bits[y * rb + (x >> 2)] >> (6 - 2 * (x & 3)))
                                 & 3u) * 85;
                        if (v > 0 && v < 255) partial++;
                    }
                }
                CHECK(partial > 0, "'A' has no antialiased edge pixels");
            }
        }
    }

    /* Same metrics for plain and bold: MIDP's getHeight() cannot depend on
     * the style. */
    for (i = 0; i < 3; i++) {
        const nj_font *p = nj_font_builtin(sizes[i], NJ_FONT_STYLE_PLAIN);
        const nj_font *b = nj_font_builtin(sizes[i], NJ_FONT_STYLE_BOLD);
        const nj_font *it = nj_font_builtin(sizes[i], NJ_FONT_STYLE_ITALIC);
        const nj_font *bi = nj_font_builtin(sizes[i],
                                            NJ_FONT_STYLE_BOLD |
                                            NJ_FONT_STYLE_ITALIC);

        CHECK(p->height == b->height && p->ascent == b->ascent &&
              p->descent == b->descent && p->glyph_w == b->glyph_w,
              "plain and bold metrics differ for size %d", sizes[i]);
        CHECK(p->bitmap != b->bitmap, "bold shares the plain bitmap");
        /* Italic has no bitmaps of its own. */
        CHECK(it->bitmap == p->bitmap, "italic must reuse the plain bitmap");
        CHECK(it->style == NJ_FONT_STYLE_ITALIC, "italic style not recorded");
        CHECK(bi->bitmap == b->bitmap,
              "bold+italic must reuse the bold bitmap");
        CHECK(bi->style == (NJ_FONT_STYLE_BOLD | NJ_FONT_STYLE_ITALIC),
              "bold+italic style not recorded");
    }

    /* Unknown sizes normalise to MEDIUM. */
    CHECK(nj_font_builtin(99, NJ_FONT_STYLE_PLAIN) ==
          nj_font_builtin(NJ_FONT_SIZE_MEDIUM, NJ_FONT_STYLE_PLAIN),
          "size 99 did not normalise to MEDIUM");
    CHECK(nj_font_builtin(-1, NJ_FONT_STYLE_PLAIN) ==
          nj_font_builtin(NJ_FONT_SIZE_MEDIUM, NJ_FONT_STYLE_PLAIN),
          "size -1 did not normalise to MEDIUM");
    /* And the three sizes really are three different faces. */
    CHECK(nj_font_builtin(NJ_FONT_SIZE_SMALL, 0)->glyph_w <
          nj_font_builtin(NJ_FONT_SIZE_MEDIUM, 0)->glyph_w,
          "SMALL should be narrower than MEDIUM");
    CHECK(nj_font_builtin(NJ_FONT_SIZE_MEDIUM, 0)->glyph_w <
          nj_font_builtin(NJ_FONT_SIZE_LARGE, 0)->glyph_w,
          "MEDIUM should be narrower than LARGE");
}

static void test_font_metrics(void)
{
    const nj_font *f = nj_font_builtin(NJ_FONT_SIZE_MEDIUM,
                                       NJ_FONT_STYLE_PLAIN);
    nj_u2 text[5];
    int i;
    int expect;

    CHECK_EQ_INT(nj_font_char_width(f, 'A'), f->glyph_w, "width of 'A'");
    CHECK_EQ_INT(nj_font_char_width(f, 0x20), f->glyph_w, "width of space");
    CHECK_EQ_INT(nj_font_char_width(f, 0xFF), f->glyph_w, "width of U+00FF");
    /* Out of the fixed cell, with no fallback: still one cell.  U+20AC is
     * outside GB2312 too, so the CJK provider does not claim it either. */
    CHECK_EQ_INT(nj_font_char_width(f, 0x20AC), f->glyph_w,
                 "width of an unrepresentable char");
    CHECK_EQ_INT(nj_font_char_width(NULL, 'A'), 0, "width with NULL font");

    /* String width is the sum of the character widths. */
    text[0] = 'H';
    text[1] = 'i';
    text[2] = 0x20;
    text[3] = 0x4E2D;
    text[4] = '!';
    expect = 0;
    for (i = 0; i < 5; i++) {
        expect += nj_font_char_width(f, text[i]);
    }
    CHECK_EQ_INT(nj_font_string_width(f, text, 5), expect,
                 "string width must be additive");
    CHECK_EQ_INT(nj_font_string_width(f, text, 0), 0, "empty string width");
    CHECK_EQ_INT(nj_font_string_width(f, NULL, 5), 0, "NULL string width");
    CHECK_EQ_INT(nj_font_string_width(NULL, text, 5), 0, "NULL font width");

    /* chars_that_fit: hand-computed against the cell width. */
    {
        const int w = f->glyph_w;
        nj_u2 run[10];
        for (i = 0; i < 10; i++) {
            run[i] = (nj_u2)('0' + i);
        }
        CHECK_EQ_INT(nj_font_chars_that_fit(f, run, 10, w - 1), 0,
                     "one pixel short of a cell fits nothing");
        CHECK_EQ_INT(nj_font_chars_that_fit(f, run, 10, w), 1,
                     "exactly one cell fits one char");
        CHECK_EQ_INT(nj_font_chars_that_fit(f, run, 10, w * 3), 3,
                     "three cells fit three chars");
        CHECK_EQ_INT(nj_font_chars_that_fit(f, run, 10, w * 3 + 1), 3,
                     "three cells and a bit still fit three chars");
        CHECK_EQ_INT(nj_font_chars_that_fit(f, run, 10, w * 100), 10,
                     "never more chars than len");
        CHECK_EQ_INT(nj_font_chars_that_fit(f, run, 10, 0), 0,
                     "zero width fits nothing");
        CHECK_EQ_INT(nj_font_chars_that_fit(f, run, 10, -5), 0,
                     "negative width fits nothing");
        CHECK_EQ_INT(nj_font_chars_that_fit(f, run, 0, 100), 0,
                     "zero length fits nothing");
        /* Monotonic in avail. */
        {
            int prev = 0;
            int avail;
            for (avail = 0; avail <= w * 12; avail++) {
                int n = nj_font_chars_that_fit(f, run, 10, avail);
                CHECK(n >= prev, "chars_that_fit decreased at avail=%d", avail);
                prev = n;
            }
        }
    }
}

static void test_font_fallback(void)
{
    nj_font cjk;
    nj_font wide;
    nj_font host;
    const nj_font *builtin = nj_font_builtin(NJ_FONT_SIZE_MEDIUM,
                                             NJ_FONT_STYLE_PLAIN);
    const int cell = builtin->glyph_w;

    /* A proportional provider: 15 px for the one glyph it can draw, 7 px for
     * everything else it is asked about. */
    memset(&cjk, 0, sizeof(cjk));
    cjk.name = "fake-cjk";
    cjk.height = 16;
    cjk.ascent = 14;
    cjk.descent = 2;
    cjk.size = NJ_FONT_SIZE_MEDIUM;
    cjk.proportional = 1;
    cjk.first_char = 0x3400u;
    cjk.last_char = 0x3401u;
    cjk.glyph_w = 16;
    cjk.glyph_h = 16;
    cjk.bitmap = NULL;
    cjk.glyph_lookup = fake_lookup;
    cjk.glyph_advance = fake_advance;

    /* A fixed-pitch wide font with no providers at all. */
    memset(&wide, 0, sizeof(wide));
    wide.name = "fake-wide";
    wide.height = 16;
    wide.ascent = 14;
    wide.descent = 2;
    wide.size = NJ_FONT_SIZE_MEDIUM;
    wide.first_char = 0x3400u;
    wide.last_char = 0x3401u;
    wide.glyph_w = 12;
    wide.glyph_h = 16;
    wide.bitmap = NULL;

    host = *builtin;              /* mutable copy, as a fontset would hold */

    /* Nothing installed: unknown characters still occupy one cell. */
    CHECK_EQ_INT(nj_font_char_width(&host, 0x3400), cell,
                 "unknown char without a fallback");
    CHECK_EQ_INT(nj_font_char_width(&host, 'A'), cell,
                 "in-range char uses the cell width");

    /* Chain: host -> cjk. */
    host.fallback = &cjk;
    CHECK_EQ_INT(nj_font_char_width(&host, 0x3401), 7,
                 "in-range fallback char uses its glyph_advance");
    CHECK_EQ_INT(nj_font_char_width(&host, 'A'), cell,
                 "this font's own cell still wins for in-range chars");
    /* 0x1234 is out of range for both; cjk is the last link, so its cell
     * width (16) is what the recursion returns. */
    CHECK_EQ_INT(nj_font_char_width(&host, 0x1234), 16,
                 "out-of-range char follows the chain to the last font");

    /* Chain: host -> wide (fixed pitch, no override). */
    host.fallback = &wide;
    CHECK_EQ_INT(nj_font_char_width(&host, 0x3400), 12,
                 "in-range fallback char uses its cell width");
    CHECK_EQ_INT(nj_font_char_width(&host, 0x3401), 12,
                 "last in-range fallback char");

    /* A provider on the host itself is consulted before the chain, and its
     * glyph_advance overrides the glyph's own width. */
    host.fallback = &cjk;
    host.glyph_lookup = fake_lookup;
    host.glyph_advance = fake_advance;
    CHECK_EQ_INT(nj_font_char_width(&host, 0x3400), 15,
                 "glyph_advance of the host font");
    CHECK_EQ_INT(nj_font_char_width(&host, 0x1234), 16,
                 "provider miss still follows the chain");
    host.glyph_lookup = NULL;
    host.glyph_advance = NULL;

    /* A cyclic fallback chain must terminate, not hang. */
    host.fallback = &host;
    CHECK_EQ_INT(nj_font_char_width(&host, 0x1234), cell,
                 "self-referential fallback terminates");
    cjk.fallback = &host;
    host.fallback = &cjk;
    CHECK_EQ_INT(nj_font_char_width(&host, 0x1234), 16,
                 "mutually recursive fallback terminates");
    cjk.fallback = NULL;

    /* NULL font. */
    CHECK_EQ_INT(nj_font_char_width(NULL, 'A'), 0, "NULL font width is 0");
}

/*
 * The real Chinese table (src/gfx/nj_font_cjk.h, generated by
 * tools/gen_cjk_font.py).  Skips itself when the build has the table off, so
 * an embedded configuration that trims it still passes.
 */
static int glyph_sample(const nj_u1 *bits, int w, int x, int y, int coverage)
{
    if (coverage == 2) {
        return ((bits[y * ((w + 3) / 4) + (x >> 2)] >> (6 - 2 * (x & 3))) & 3u) * 85;
    }
    return ((bits[y * ((w + 7) / 8) + (x >> 3)] >> (7 - (x & 7))) & 1u) * 255;
}

static int glyph_ink(const nj_u1 *bits, int w, int h, int coverage)
{
    int y;
    int x;
    int ink = 0;

    for (y = 0; y < h; y++) {
        for (x = 0; x < w; x++) {
            if (glyph_sample(bits, w, x, y, coverage)) {
                ink++;
            }
        }
    }
    return ink;
}

static void test_font_cjk_table(void)
{
    /* 中 文 游 戏 */
    static const nj_u2 hanzi[4] = { 0x4E2Du, 0x6587u, 0x6E38u, 0x620Fu };
    const nj_font *small = nj_font_builtin(NJ_FONT_SIZE_SMALL, NJ_FONT_STYLE_PLAIN);
    const nj_font *medium = nj_font_builtin(NJ_FONT_SIZE_MEDIUM, NJ_FONT_STYLE_PLAIN);
    const nj_font *large = nj_font_builtin(NJ_FONT_SIZE_LARGE, NJ_FONT_STYLE_PLAIN);
    int i;

    if (small == NULL || small->glyph_lookup == NULL) {
        printf("  (CJK table not compiled in: NJ_ENABLE_FONT_CJK=0)\n");
        return;
    }
    CHECK(medium != NULL && medium->glyph_lookup != NULL,
          "medium has no CJK provider");
    CHECK(large != NULL && large->glyph_lookup != NULL,
          "large has no CJK provider");
    CHECK_EQ_INT(small->glyph_ascent, 12, "small provider baseline");
    CHECK_EQ_INT(medium->glyph_ascent, 12, "shared small/medium bitmap baseline");
    CHECK_EQ_INT(large->glyph_ascent, 16, "large provider baseline");
    {
        int w = 0, h = 0;
        const nj_u1 *bits = large->glyph_lookup(large->glyph_ud, 0xFF47u, &w, &h);
        CHECK(bits != NULL, "fullwidth g keeps its descender");
        CHECK_EQ_INT(w, 16, "large fullwidth glyph width");
        CHECK_EQ_INT(h, 20, "large storage preserves accents and descenders");
    }

    for (i = 0; i < 4; i++) {
        CHECK_EQ_INT(nj_font_char_width(small, hanzi[i]), 12, "small hanzi advance");
        CHECK_EQ_INT(nj_font_char_width(medium, hanzi[i]), 12, "medium hanzi advance");
        CHECK_EQ_INT(nj_font_char_width(large, hanzi[i]), 16, "large hanzi advance");
    }
    /*
     * The provider must claim Chinese only: ASCII, Latin-1 and code points
     * outside GB2312 keep the fixed cell and the fallback chain.
     */
    CHECK_EQ_INT(nj_font_char_width(small, 'A'), small->glyph_w,
                 "ASCII keeps its cell");
    CHECK_EQ_INT(nj_font_char_width(large, 0x00E9u), large->glyph_w,
                 "Latin-1 keeps its cell");
    CHECK_EQ_INT(nj_font_char_width(small, 0x20ACu), small->glyph_w,
                 "a code point outside GB2312 keeps the cell");

    for (i = 0; i < 4; i++) {
        const nj_u1 *bits;
        int w = 0;
        int h = 0;
        int ink;

        bits = small->glyph_lookup(small->glyph_ud, hanzi[i], &w, &h);
        CHECK(bits != NULL, "lookup missed U+%04X", hanzi[i]);
        CHECK_EQ_INT(w, 12, "glyph width");
        CHECK_EQ_INT(h, 16, "glyph storage height preserves descenders");
        if (bits == NULL) {
            continue;
        }
        ink = glyph_ink(bits, w, h, small->coverage);
        CHECK(ink >= 6 && ink <= 120, "U+%04X ink is %d, expected a real glyph",
              hanzi[i], ink);
        if (small->coverage == 2) {
            int x, y, partial = 0;
            for (y = 0; y < h; y++) {
                for (x = 0; x < w; x++) {
                    int v = glyph_sample(bits, w, x, y, small->coverage);
                    if (v > 0 && v < 255) partial++;
                }
            }
            CHECK(partial > 0, "U+%04X lost its antialiased edges", hanzi[i]);
        }

        if (i > 0) {
            const nj_u1 *prev = small->glyph_lookup(small->glyph_ud, hanzi[i - 1],
                                                    &w, &h);
            CHECK(prev != NULL &&
                      memcmp(prev, bits, (size_t)((w * (small->coverage == 2 ? 2 : 1) + 7) / 8) * (size_t)h) != 0,
                  "U+%04X and U+%04X decoded to the same rows", hanzi[i - 1],
                  hanzi[i]);
        }
    }

    /* Stranded II's menu exposed whole-glyph jumps under target-size MONO
     * hinting: 始/绍/关/出 ended one pixel above 游/戏/设. These full-height
     * Han outlines share a bottom edge at both em sizes. Preserve natural
     * top-edge differences (especially at 15 px), rather than fitting boxes. */
    {
        static const nj_u2 menu[] = {
            0x5F00u, 0x59CBu, 0x6E38u, 0x620Fu, 0x8BBEu, 0x7F6Eu,
            0x4ECBu, 0x7ECDu, 0x5173u, 0x4E8Eu, 0x9000u, 0x51FAu
        };
        const nj_font *faces[] = { small, medium, large };
        int face, ch;
        for (face = 0; face < 3; face++) {
            const nj_font *f = faces[face];
            for (ch = 0; ch < (int)(sizeof(menu) / sizeof(menu[0])); ch++) {
                int w = 0, h = 0, top = -1, bottom = -1, x, y;
                const nj_u1 *bits = f->glyph_lookup(f->glyph_ud, menu[ch], &w, &h);
                CHECK(bits != NULL, "menu glyph U+%04X is present", menu[ch]);
                if (!bits) continue;
                for (y = 0; y < h; y++) {
                    for (x = 0; x < w; x++) {
                        if (glyph_sample(bits, w, x, y, f->coverage) >= 170) {
                            if (top < 0) top = y;
                            bottom = y;
                        }
                    }
                }
                CHECK_EQ_INT(bottom, f->glyph_ascent, "menu Han bottom stays on shared row");
                CHECK(top >= f->glyph_ascent - (face == 2 ? 13 : 9) &&
                      top <= f->glyph_ascent - (face == 2 ? 12 : 9),
                      "menu glyph U+%04X has stable height (top %d)", menu[ch], top);
            }
        }
    }

    /* Shared downsampling must not erase thin symbols. */
    {
        static const nj_u2 symbols[] = { 0x2016u, 0xFF3Fu };
        const nj_font *faces[] = { small, large };
        int face, ch;
        for (face = 0; face < 2; face++) {
            for (ch = 0; ch < 2; ch++) {
                int w = 0, h = 0;
                const nj_u1 *bits = faces[face]->glyph_lookup(NULL, symbols[ch], &w, &h);
                CHECK(bits && glyph_ink(bits, w, h, faces[face]->coverage) > 0,
                      "thin glyph U+%04X retains ink", symbols[ch]);
            }
        }
    }

    /* U+3000 IDEOGRAPHIC SPACE is the one blank cell in the table: it must
     * advance a full cell and draw nothing. */
    {
        const nj_u1 *bits;
        int w = 0;
        int h = 0;

        CHECK_EQ_INT(nj_font_char_width(small, 0x3000u), 12,
                     "ideographic space advances a full cell");
        bits = small->glyph_lookup(small->glyph_ud, 0x3000u, &w, &h);
        CHECK(bits != NULL, "lookup missed U+3000");
        if (bits != NULL) {
            CHECK_EQ_INT(glyph_ink(bits, w, h, small->coverage), 0, "ideographic space ink");
        }
    }

    /* A whole sentence: every hanzi is claimed, the ASCII comma is not. */
    {
        static const nj_u2 sentence[5] = { 0x4E2Du, 0x6587u, ',', 0x6E38u, 0x620Fu };
        CHECK_EQ_INT(nj_font_string_width(small, sentence, 5),
                     (12 + 12 + small->glyph_w + 12 + 12), "mixed sentence width");
    }
}

static void test_fontset(void)
{
    nj_fontset fs;
    nj_fontset fs2;
    const nj_font *f;
    const nj_font *fb = nj_font_builtin(NJ_FONT_SIZE_SMALL,
                                        NJ_FONT_STYLE_PLAIN);
    int i;

    memset(&fs, 0, sizeof(fs));
    CHECK_EQ_INT(fs.initialized, 0, "fresh fontset is not initialized");

    /* set_fallback on an uninitialised set must still work. */
    nj_fontset_set_fallback(&fs, fb);
    CHECK_EQ_INT(fs.initialized, 1, "set_fallback initialised the set");
    CHECK_EQ_INT(fs.count, NJ_FONTSET_SLOTS, "fontset slot count");

    nj_fontset_init(&fs);
    nj_fontset_init(&fs);
    CHECK_EQ_INT(fs.count, NJ_FONTSET_SLOTS, "init is idempotent (count)");
    CHECK_EQ_INT(fs.initialized, 1, "init is idempotent (flag)");

    /* Every slot points at the builtin of its (size, bold) pair and carries
     * the fallback we installed. */
    for (i = 0; i < NJ_FONTSET_SLOTS; i++) {
        CHECK(fs.fonts[i].fallback == fb, "slot %d lost the fallback", i);
        CHECK(fs.fonts[i].bitmap != NULL, "slot %d has no bitmap", i);
    }
    CHECK(fs.fonts[0].bitmap ==
          nj_font_builtin(NJ_FONT_SIZE_SMALL, NJ_FONT_STYLE_PLAIN)->bitmap,
          "slot 0 is SMALL plain");
    CHECK(fs.fonts[1].bitmap ==
          nj_font_builtin(NJ_FONT_SIZE_SMALL, NJ_FONT_STYLE_BOLD)->bitmap,
          "slot 1 is SMALL bold");
    CHECK(fs.fonts[4].bitmap ==
          nj_font_builtin(NJ_FONT_SIZE_LARGE, NJ_FONT_STYLE_PLAIN)->bitmap,
          "slot 4 is LARGE plain");

    /* get() returns a pointer into the set. */
    f = nj_fontset_get(&fs, NJ_FONT_SIZE_MEDIUM, NJ_FONT_STYLE_PLAIN);
    CHECK(f == &fs.fonts[2], "MEDIUM plain is slot 2");
    CHECK(f->fallback == fb, "the returned font kept the fallback");
    f = nj_fontset_get(&fs, NJ_FONT_SIZE_MEDIUM, NJ_FONT_STYLE_BOLD);
    CHECK(f == &fs.fonts[3], "MEDIUM bold is slot 3");
    f = nj_fontset_get(&fs, NJ_FONT_SIZE_LARGE, NJ_FONT_STYLE_BOLD |
                       NJ_FONT_STYLE_ITALIC);
    CHECK(f == &fs.fonts[5], "LARGE bold+italic is slot 5");

    /* Unknown sizes degrade to MEDIUM rather than reading out of bounds. */
    f = nj_fontset_get(&fs, 12345, NJ_FONT_STYLE_PLAIN);
    CHECK(f == &fs.fonts[2], "unknown size maps to MEDIUM");

    /* Auto-init with no static state: a second set is independent. */
    memset(&fs2, 0, sizeof(fs2));
    f = nj_fontset_get(&fs2, NJ_FONT_SIZE_SMALL, NJ_FONT_STYLE_PLAIN);
    CHECK_EQ_INT(fs2.initialized, 1, "get() auto-initialised the set");
    CHECK(f == &fs2.fonts[0], "get() returned a pointer into fs2");
    CHECK(f->fallback == NULL, "fs2 has no fallback");
    CHECK(fs.fonts[0].fallback == fb, "fs still has its fallback");

    /* Clearing. */
    nj_fontset_set_fallback(&fs, NULL);
    for (i = 0; i < NJ_FONTSET_SLOTS; i++) {
        CHECK(fs.fonts[i].fallback == NULL, "slot %d kept the fallback", i);
    }

    /* NULL set degrades to the immutable builtin. */
    f = nj_fontset_get(NULL, NJ_FONT_SIZE_LARGE, NJ_FONT_STYLE_BOLD);
    CHECK(f == nj_font_builtin(NJ_FONT_SIZE_LARGE, NJ_FONT_STYLE_BOLD),
          "NULL fontset must degrade to the builtin");
    nj_fontset_set_fallback(NULL, fb);
    nj_fontset_init(NULL);
    CHECK(1, "NULL fontset calls are no-ops");
}

/* ------------------------------------------------------------------ */
/* PNG tests                                                           */
/* ------------------------------------------------------------------ */
static int pixels_match(const char *path, const nj_image *img, char *why,
                        size_t why_len)
{
    size_t size = 0;
    unsigned char *raw = (unsigned char *)xread(path, &size);
    size_t expect = (size_t)img->width * (size_t)img->height * 4u;
    size_t i;

    if (raw == NULL) {
        snprintf(why, why_len, "cannot read %s", path);
        return 0;
    }
    if (size != expect) {
        snprintf(why, why_len, "%s is %lu bytes, expected %lu",
                 path, (unsigned long)size, (unsigned long)expect);
        free(raw);
        return 0;
    }
    for (i = 0; i < expect; i += 4u) {
        nj_u4 want = (nj_u4)raw[i] | ((nj_u4)raw[i + 1] << 8) |
                     ((nj_u4)raw[i + 2] << 16) | ((nj_u4)raw[i + 3] << 24);
        if (img->pixels[i / 4u] != want) {
            snprintf(why, why_len,
                     "pixel %lu: got 0x%08X want 0x%08X",
                     (unsigned long)(i / 4u),
                     (unsigned)img->pixels[i / 4u], (unsigned)want);
            free(raw);
            return 0;
        }
    }
    free(raw);
    return 1;
}

static void test_png_positives(const char *dir)
{
    char path[1024];
    char line[1024];
    FILE *fh;
    int count = 0;

    snprintf(path, sizeof(path), "%s/positive.txt", dir);
    fh = fopen(path, "r");
    if (fh == NULL) {
        CHECK(0, "cannot open %s (run tests/gen_png_fixtures.py)", path);
        return;
    }

    while (fgets(line, (int)sizeof(line), fh) != NULL) {
        char name[256];
        int width = 0;
        int height = 0;
        int has_alpha = 0;
        size_t size = 0;
        unsigned char *png;
        nj_image *img;
        const char *err = NULL;
        char why[512];

        if (line[0] == '#' || line[0] == '\n') {
            continue;
        }
        if (sscanf(line, "%255s %d %d %d", name, &width, &height,
                   &has_alpha) != 4) {
            CHECK(0, "bad manifest line: %s", line);
            continue;
        }
        count++;

        snprintf(path, sizeof(path), "%s/%s.png", dir, name);
        png = (unsigned char *)xread(path, &size);
        CHECK(png != NULL, "%s: cannot read fixture", name);
        if (png == NULL) {
            continue;
        }

        img = nj_png_decode(png, (nj_u4)size, NULL, NULL, NULL, &err);
        CHECK(img != NULL, "%s: decode failed: %s", name,
              err != NULL ? err : "(no message)");
        if (img != NULL) {
            CHECK_EQ_INT(img->width, width, name);
            CHECK_EQ_INT(img->height, height, name);
            CHECK_EQ_INT(img->format, NJ_PIXFMT_ARGB8888, name);
            CHECK_EQ_INT(img->has_alpha, has_alpha, name);
            CHECK(img->pixels != NULL, "%s: no pixels", name);

            snprintf(path, sizeof(path), "%s/%s.argb", dir, name);
            why[0] = '\0';
            CHECK(pixels_match(path, img, why, sizeof(why)),
                  "%s: %s", name, why);
            nj_image_free(img, NULL, NULL);
        }
        free(png);
    }
    fclose(fh);
    printf("  %d positive fixtures decoded and compared\n", count);
    CHECK(count >= 20, "expected at least 20 positive fixtures, saw %d",
          count);
}

static void test_png_negatives(const char *dir)
{
    char path[1024];
    char line[1024];
    FILE *fh;
    int count = 0;

    snprintf(path, sizeof(path), "%s/negative.txt", dir);
    fh = fopen(path, "r");
    if (fh == NULL) {
        CHECK(0, "cannot open %s (run tests/gen_png_fixtures.py)", path);
        return;
    }

    while (fgets(line, (int)sizeof(line), fh) != NULL) {
        char name[256];
        char expect[128];
        size_t size = 0;
        unsigned char *png;
        nj_image *img;
        const char *err = NULL;

        if (line[0] == '#' || line[0] == '\n') {
            continue;
        }
        if (sscanf(line, "%255s %127s", name, expect) != 2) {
            CHECK(0, "bad manifest line: %s", line);
            continue;
        }
        count++;

        snprintf(path, sizeof(path), "%s/%s.png", dir, name);
        png = (unsigned char *)xread(path, &size);
        CHECK(png != NULL, "%s: cannot read fixture", name);
        if (png == NULL) {
            continue;
        }

        err = NULL;
        img = nj_png_decode(png, (nj_u4)size, NULL, NULL, NULL, &err);
        CHECK(img == NULL, "%s: decoder accepted a broken file", name);
        CHECK(err != NULL, "%s: failure without an error message", name);
        if (err != NULL) {
            CHECK(strstr(err, expect) != NULL,
                  "%s: error %.*s does not mention '%s'", name, 120, err,
                  expect);
        }
        if (img != NULL) {
            nj_image_free(img, NULL, NULL);
        }
        free(png);
    }
    fclose(fh);
    printf("  %d negative fixtures rejected with a message\n", count);
    CHECK(count >= 15, "expected at least 15 negative fixtures, saw %d",
          count);
}

static void test_png_api(const char *dir)
{
    char path[1024];
    size_t size = 0;
    unsigned char *png;
    nj_image *img;
    const char *err = NULL;
    alloc_stats st;
    int i;

    /* Trivial argument handling. */
    err = NULL;
    CHECK(nj_png_decode(NULL, 0, NULL, NULL, NULL, &err) == NULL,
          "NULL data must fail");
    CHECK(err != NULL, "NULL data must set an error");
    err = NULL;
    CHECK(nj_png_decode("hello", 5, NULL, NULL, NULL, &err) == NULL,
          "a short non-PNG buffer must fail");
    CHECK(err != NULL, "short buffer must set an error");
    /* A NULL err pointer must not crash. */
    CHECK(nj_png_decode(NULL, 0, NULL, NULL, NULL, NULL) == NULL,
          "NULL err pointer must be tolerated");

    /* nj_image_create. */
    img = nj_image_create(4, 3, NULL, NULL);
    CHECK(img != NULL, "nj_image_create failed");
    if (img != NULL) {
        CHECK_EQ_INT(img->width, 4, "created width");
        CHECK_EQ_INT(img->height, 3, "created height");
        for (i = 0; i < 12; i++) {
            CHECK_EQ_INT(img->pixels[i], 0u, "created image must be zeroed");
        }
        nj_image_free(img, NULL, NULL);
    }
    CHECK(nj_image_create(0, 4, NULL, NULL) == NULL, "width 0 must fail");
    CHECK(nj_image_create(4, 0, NULL, NULL) == NULL, "height 0 must fail");
    CHECK(nj_image_create(-1, 4, NULL, NULL) == NULL, "negative must fail");
    /*
     * The dimension cap is 65535 and the real bound is the pixel count: a wide
     * and short sheet is allowed (浴火银河2完整版_7689 ships a 5456x15 PNG),
     * while a side past 65535 or more than 16.7 million pixels is refused.
     */
    img = nj_image_create(5000, 4, NULL, NULL);
    CHECK(img != NULL, "a wide short image must be allowed");
    if (img != NULL) {
        CHECK_EQ_INT(img->width, 5000, "wide image width");
        nj_image_free(img, NULL, NULL);
    }
    CHECK(nj_image_create(65536, 1, NULL, NULL) == NULL,
          "a side past 65535 must fail");
    CHECK(nj_image_create(5000, 5000, NULL, NULL) == NULL,
          "more than 16.7 million pixels must fail");
    nj_image_free(NULL, NULL, NULL);   /* must be a no-op */

    /* nj_image_load sniffs the container. */
    snprintf(path, sizeof(path), "%s/sniff_jpeg.bin", dir);
    png = (unsigned char *)xread(path, &size);
    if (png != NULL) {
        err = NULL;
        CHECK(nj_image_load(png, (nj_u4)size, NULL, NULL, NULL, &err) == NULL,
              "JPEG must not decode");
        CHECK(err != NULL && strstr(err, "JPEG") != NULL,
              "JPEG must report 'JPEG support not built', got %s",
              err != NULL ? err : "(null)");
        free(png);
    } else {
        CHECK(0, "cannot read %s", path);
    }
    snprintf(path, sizeof(path), "%s/sniff_unknown.bin", dir);
    png = (unsigned char *)xread(path, &size);
    if (png != NULL) {
        err = NULL;
        CHECK(nj_image_load(png, (nj_u4)size, NULL, NULL, NULL, &err) == NULL,
              "unknown format must fail");
        CHECK(err != NULL, "unknown format must set an error");
        free(png);
    } else {
        CHECK(0, "cannot read %s", path);
    }

    /* A real PNG through load(), decoded with the VM-style allocator while
     * counting every allocation. */
    snprintf(path, sizeof(path), "%s/palette8_trns.png", dir);
    png = (unsigned char *)xread(path, &size);
    if (png == NULL) {
        CHECK(0, "cannot read %s", path);
        return;
    }
    memset(&st, 0, sizeof(st));
    err = NULL;
    img = nj_image_load(png, (nj_u4)size, counting_alloc, &st, counting_free,
                        &err);
    CHECK(img != NULL, "load(palette8_trns) failed: %s",
          err != NULL ? err : "(no message)");
    CHECK(st.allocs > 0, "the counting allocator was not used");
    if (img != NULL) {
        char why[256];
        snprintf(path, sizeof(path), "%s/palette8_trns.argb", dir);
        why[0] = '\0';
        CHECK(pixels_match(path, img, why, sizeof(why)), "%s", why);
        nj_image_free(img, counting_free, &st);
    }
    CHECK_EQ_INT(st.allocs, st.frees,
                 "every buffer must be released after nj_image_free");
    free(png);

    /* Failure paths must not leak either. */
    {
        static const char *broken[4] = {
            "neg_bad_crc", "neg_bad_deflate", "neg_short_idat",
            "neg_truncated"
        };
        int k;
        for (k = 0; k < 4; k++) {
            snprintf(path, sizeof(path), "%s/%s.png", dir, broken[k]);
            png = (unsigned char *)xread(path, &size);
            CHECK(png != NULL, "cannot read %s", path);
            if (png == NULL) {
                continue;
            }
            memset(&st, 0, sizeof(st));
            err = NULL;
            img = nj_png_decode(png, (nj_u4)size, counting_alloc, &st,
                                counting_free, &err);
            CHECK(img == NULL, "%s must fail", broken[k]);
            CHECK_EQ_INT(st.allocs, st.frees,
                         "error path must release every buffer");
            free(png);
        }
    }

    /* The decoder must not read past the end of a smaller-than-declared
     * buffer: feed it a valid file with the tail cut off at every length. */
    snprintf(path, sizeof(path), "%s/rgb8.png", dir);
    png = (unsigned char *)xread(path, &size);
    if (png != NULL) {
        nj_u4 cut;
        int survived = 1;
        for (cut = 0; cut < (nj_u4)size; cut += 7u) {
            const char *e2 = NULL;
            nj_image *im2 = nj_png_decode(png, cut, NULL, NULL, NULL, &e2);
            if (im2 != NULL) {
                nj_image_free(im2, NULL, NULL);
                /* complete-file lengths are allowed to succeed */
                if (cut < (nj_u4)size) {
                    survived = 0;
                    break;
                }
            }
        }
        CHECK(survived, "a truncated buffer must never decode successfully");
        free(png);
    }
}


/* ------------------------------------------------------------------ */
/* Mutation fuzzing: the decoder eats untrusted game assets, so it must  */
/* never crash, hang or read out of bounds whatever the bytes say.       */
/* ------------------------------------------------------------------ */
static nj_u4 rd32(const unsigned char *p)
{
    return ((nj_u4)p[0] << 24) | ((nj_u4)p[1] << 16) |
           ((nj_u4)p[2] << 8) | (nj_u4)p[3];
}

static void wr32(unsigned char *p, nj_u4 v)
{
    p[0] = (unsigned char)(v >> 24);
    p[1] = (unsigned char)(v >> 16);
    p[2] = (unsigned char)(v >> 8);
    p[3] = (unsigned char)v;
}

static nj_u4 fuzz_next(nj_u4 *state)
{
    nj_u4 x = *state;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    *state = x;
    return x;
}

/* Recompute the CRC of the chunk that contains `at`. */
static int fix_chunk_crc(unsigned char *buf, size_t size, size_t at)
{
    size_t pos = 8;

    while (pos + 12u <= size) {
        nj_u4 len = rd32(buf + pos);
        if (pos + 12u + (size_t)len > size) {
            return 0;
        }
        if (at >= pos + 4u && at < pos + 8u + (size_t)len) {
            nj_u4 crc = 0;   /* nj_crc32 is not exported to the test; use the
                              * decoder's own by re-inflating? No: compute it
                              * with a local table-free implementation. */
            size_t i;
            nj_u4 c = 0xFFFFFFFFu;
            for (i = pos + 4u; i < pos + 8u + (size_t)len; i++) {
                int k;
                c ^= buf[i];
                for (k = 0; k < 8; k++) {
                    c = (c & 1u) ? ((c >> 1) ^ 0xEDB88320u) : (c >> 1);
                }
            }
            crc = c ^ 0xFFFFFFFFu;
            wr32(buf + pos + 8u + (size_t)len, crc);
            return 1;
        }
        pos += 12u + (size_t)len;
    }
    return 0;
}

/* An allocator that fails on demand: exercises every cleanup path. */
typedef struct fail_alloc {
    int budget;
    int allocs;
    int frees;
} fail_alloc;

static void *budget_alloc(void *ud, nj_size size)
{
    fail_alloc *f = (fail_alloc *)ud;

    if (f->allocs >= f->budget) {
        return NULL;
    }
    f->allocs++;
    return malloc((size_t)size);
}

static void budget_free(void *ud, void *p)
{
    fail_alloc *f = (fail_alloc *)ud;

    if (p != NULL) {
        f->frees++;
        free(p);
    }
}

static void test_png_out_of_memory(const char *dir)
{
    static const char *cases[3] = { "rgba8", "interlace_rgb8",
                                    "palette256_trns" };
    int c;

    for (c = 0; c < 3; c++) {
        char path[1024];
        size_t size = 0;
        unsigned char *png;
        int budget;

        snprintf(path, sizeof(path), "%s/%s.png", dir, cases[c]);
        png = (unsigned char *)xread(path, &size);
        CHECK(png != NULL, "cannot read %s", path);
        if (png == NULL) {
            continue;
        }
        /* Let the decoder have 0..6 buffers; every step must either succeed
         * or fail cleanly without leaking what it already took. */
        for (budget = 0; budget <= 6; budget++) {
            fail_alloc fa;
            const char *err = NULL;
            nj_image *img;

            fa.budget = budget;
            fa.allocs = 0;
            fa.frees = 0;
            img = nj_png_decode(png, (nj_u4)size, budget_alloc, &fa,
                                budget_free, &err);
            if (img == NULL) {
                CHECK(err != NULL, "%s: OOM failure without a message",
                      cases[c]);
            } else {
                nj_image_free(img, budget_free, &fa);
            }
            CHECK_EQ_INT(fa.allocs, fa.frees,
                         "allocator failure must not leak");
        }
        free(png);
    }
    printf("  allocator-failure paths released every partial allocation\n");
}

static void test_png_fuzz(const char *dir)
{
    static const char *bases[] = {
        "rgb8", "rgba8", "palette8_trns", "grey1", "grey4", "grey16",
        "interlace_rgb8", "multi_idat",
    };
    nj_u4 state = 0x12345678u;
    int rounds = 0;
    int b;
    int accepted = 0;

    for (b = 0; b < (int)(sizeof(bases) / sizeof(bases[0])); b++) {
        char path[1024];
        size_t size = 0;
        unsigned char *base = NULL;
        int iteration;

        snprintf(path, sizeof(path), "%s/%s.png", dir, bases[b]);
        base = (unsigned char *)xread(path, &size);
        if (base == NULL || size < 32u) {
            CHECK(0, "fuzz: cannot read %s", path);
            free(base);
            continue;
        }

        for (iteration = 0; iteration < 300; iteration++) {
            unsigned char *buf = (unsigned char *)malloc(size);
            size_t len = size;
            nj_u4 r = fuzz_next(&state);
            nj_image *img;
            const char *err = NULL;

            if (buf == NULL) {
                CHECK(0, "fuzz: out of memory");
                break;
            }
            memcpy(buf, base, size);

            switch (r % 5u) {
            case 0:   /* single bit flip anywhere */
                buf[fuzz_next(&state) % size] ^=
                    (unsigned char)(1u << (fuzz_next(&state) % 8u));
                break;
            case 1: { /* flip a payload byte and repair that chunk's CRC */
                size_t at = (size_t)(fuzz_next(&state) % size);
                buf[at] ^= 0xFFu;
                (void)fix_chunk_crc(buf, size, at);
                break;
            }
            case 2:   /* truncate */
                len = (size_t)(fuzz_next(&state) % size);
                break;
            case 3: { /* random IHDR geometry with a valid CRC */
                size_t i;
                for (i = 8u; i < 8u + 4u + 25u && i < size; i++) {
                    buf[i] = (unsigned char)(fuzz_next(&state) & 0xFFu);
                }
                (void)fix_chunk_crc(buf, size, 8u + 8u);
                break;
            }
            default:  /* random byte in the IDAT payload */
                buf[size / 2u] = (unsigned char)(fuzz_next(&state) & 0xFFu);
                (void)fix_chunk_crc(buf, size, size / 2u);
                break;
            }

            img = nj_png_decode(buf, (nj_u4)len, NULL, NULL, NULL, &err);
            rounds++;
            if (img != NULL) {
                accepted++;
                CHECK(img->width > 0 && img->height > 0,
                      "fuzz produced a degenerate image");
                nj_image_free(img, NULL, NULL);
            } else {
                CHECK(err != NULL, "fuzz failure without an error message");
            }
            free(buf);
        }
        free(base);
    }
    printf("  %d mutated inputs decoded without a crash (%d accepted)\n",
           rounds, accepted);
    CHECK(rounds >= 2000, "fuzz did not run enough rounds");
}

